
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m06_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m06_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.504788429476124e+00, -1.475649841387072e+00, -1.438949682458745e+00, -1.396418067532914e+00, -1.352924574946388e+00, -1.311274965170611e+00, -1.251071955337842e+00, -1.141699427955546e+00, -1.025511052334428e+00, -7.668476567731437e-01, -6.261409654218253e-01, -3.573100761385629e-01, -2.637805241092725e-01, -2.228203812927343e-01, -1.813291049253963e-01, -1.416103047351277e-01, -1.093360944866542e-01, -7.356678871128980e-02, -1.800711761307058e-02, -2.037606681645285e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


